-- generated by storm; review before applying
-- 4 step(s)

CREATE TABLE "answer_days" (
    "model_id" text NOT NULL,
    "day" timestamptz NOT NULL,
    "answers" int8 DEFAULT 0 NOT NULL,
    "feedback" int8 DEFAULT 0 NOT NULL,
    "correct" int8 DEFAULT 0 NOT NULL,
    PRIMARY KEY ("model_id", "day"),
    CONSTRAINT "ck_answer_days_answers_0_and_feedback_0_and_correct_0" CHECK ((answers >= 0) AND (feedback >= 0) AND (correct >= 0))
);
CREATE INDEX "ix_answer_days_day" ON "answer_days" ("day");
CREATE TABLE "answers" (
    "id" text NOT NULL,
    "create_time" timestamptz NOT NULL,
    "model_id" text NOT NULL,
    "version_id" text DEFAULT ''::text NOT NULL,
    "label" text DEFAULT ''::text NOT NULL,
    "value" float8 DEFAULT 0 NOT NULL,
    "confidence" float8 DEFAULT 0 NOT NULL,
    "fields" jsonb DEFAULT '{}'::jsonb NOT NULL,
    "feedback_time" timestamptz,
    "truth_label" text DEFAULT ''::text NOT NULL,
    "truth_value" float8 DEFAULT 0 NOT NULL,
    "correct" bool DEFAULT false NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "ck_answers_length_label_200" CHECK (length(label) <= 200),
    CONSTRAINT "ck_answers_length_truth_label_200" CHECK (length(truth_label) <= 200)
);
CREATE INDEX "ix_answers_create_time" ON "answers" USING brin ("create_time");
CREATE INDEX "ix_answers_model_id_create_time" ON "answers" ("model_id", "create_time" DESC);
ALTER TABLE "answer_days" ADD CONSTRAINT "fk_answer_days_model_id" FOREIGN KEY ("model_id") REFERENCES "models" ("id") ON DELETE CASCADE;
ALTER TABLE "answers" ADD CONSTRAINT "fk_answers_model_id" FOREIGN KEY ("model_id") REFERENCES "models" ("id") ON DELETE CASCADE;
